<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue'
import {tradingApi,tradingOnline} from './auto-trading-client.js'
import {mountTradingDashboard,money,date} from './trading-dashboard.js'
const emit=defineEmits(['access-revoked']),rows=ref([]),search=ref(''),filter=ref(''),archived=ref(false),error=ref(''),busy=ref(false),id=ref(''),host=ref(null),item=ref(null),form=ref(null),pair=ref(null)
let view,timer,disposed=false,loading=false,generation=0
const shown=computed(()=>rows.value.filter(x=>(!search.value||[x.name,x.symbol,x.account_alias].join(' ').toLowerCase().includes(search.value.toLowerCase()))&&(!filter.value||(filter.value==='error'?!tradingOnline(x)||(!x.snapshot?.ready&&!!x.last_seen):filter.value==='running'?tradingOnline(x)&&x.snapshot?.entries:tradingOnline(x)&&!x.snapshot?.entries))))
async function api(action,p){try{return await tradingApi(action,p)}catch(e){if(e.accessDenied){rows.value=[];item.value=null;view?.destroy();emit('access-revoked')}throw e}}
async function load(){if(loading||disposed)return;loading=true;try{const data=await api('list',{archived:archived.value});if(!disposed)rows.value=data;error.value=''}catch(e){error.value=e.message}finally{loading=false}}
async function route(){const epoch=++generation;view?.destroy();view=null;pair.value=null;id.value=new URLSearchParams(location.hash.split('?')[1]||'').get('trading')||'';item.value=null;error.value='';if(!id.value){await load();return}const selectedId=id.value;try{const data=await api('get',{id:selectedId});if(disposed||epoch!==generation)return;item.value=data.item;await nextTick();if(!host.value)return;view=mountTradingDashboard(host.value,{
 getStatus:async()=>{const fresh=await api('get',{id:selectedId});if(epoch===generation&&!disposed)item.value=fresh.item;return {...fresh.item.snapshot,name:fresh.item.name,last_seen:fresh.item.last_seen,commands:fresh.commands}},
 isOnline:s=>!!s.last_seen&&Date.now()-Date.parse(s.last_seen)<15000,
 getEvents:offset=>api('events',{id:selectedId,offset}),
 command:(action,p)=>api('command',{id:selectedId,action,command_id:crypto.randomUUID(),...p})
 })}catch(e){error.value=e.message}}
function newItem(){form.value={name:'',account_alias:'',symbol:'',timeframe:'10S'}}
function editItem(x){form.value={id:x.id,name:x.name,account_alias:x.account_alias,symbol:x.symbol,timeframe:x.timeframe,version:x.version}}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function save(){await run(async()=>{const data=await api('save',form.value);form.value=null;await load();if(id.value)item.value=data})}
async function pairCode(){await run(async()=>{pair.value=await api('pair',{id:id.value})})}
async function change(action,x){if(!confirm(x.name+' · '+({'archive':'보관','restore':'복원','disconnect':'PC 연결 해제'}[action])+'할까요?'))return;await run(async()=>{const updated=await api(action,{id:x.id,version:x.version});if(id.value)item.value=updated;await load()})}
onMounted(()=>{route();window.addEventListener('hashchange',route);timer=setInterval(()=>{if(!id.value)load()},5000)})
onUnmounted(()=>{disposed=true;++generation;clearInterval(timer);view?.destroy();window.removeEventListener('hashchange',route)})
</script>
<template><main class="at-center"><header><div><span class="at-eyebrow">PMOFFICE · BINANCE DEMO</span><h1>Auto Trading 센터</h1><p>모의 자동 거래의 실행 현황과 손익을 확인하고 관리합니다.</p></div><a v-if="id" href="/admin/#auto-trading">전체 거래 목록</a><button v-else :disabled="busy" @click="newItem">새 모의 거래 등록</button></header>
<p v-if="error" role="alert">{{error}}</p>
<form v-if="form" class="at-form" @submit.prevent="save"><h2>{{form.id?'거래 이름 변경':'새 모의 거래 등록'}}</h2><label>거래 이름<input v-model="form.name" maxlength="160" required></label><template v-if="!form.id"><label>Demo 계정 이름<input v-model="form.account_alias" maxlength="80" required placeholder="같은 계정은 같은 이름을 사용하세요"></label><label>거래소 종목<input v-model="form.symbol" pattern="[A-Z0-9]{2,24}" required placeholder="SOXLUSDT"></label><label>시간봉<input v-model="form.timeframe" maxlength="20" required></label><p>별도로 준비한 모의 거래 프로그램을 연결합니다. 같은 Demo 계정·종목은 동시에 등록할 수 없습니다.</p></template><button :disabled="busy">저장</button><button type="button" @click="form=null">취소</button></form>
<template v-if="!id"><div class="at-toolbar"><label>거래 검색<input v-model="search" placeholder="이름·종목·계정"></label><label>상태<select v-model="filter"><option value="">전체</option><option value="running">실행</option><option value="stopped">중지</option><option value="error">오류·연결 확인</option></select></label><label><input v-model="archived" type="checkbox" @change="load">보관 항목 보기</label></div>
<div class="at-table"><table><thead><tr><th>거래 이름</th><th>종목·시간봉</th><th>실행·연결</th><th>보유</th><th>오늘 순손익</th><th>마지막 확인(KST)</th><th>관리</th></tr></thead><tbody><tr v-for="x in shown" :key="x.id"><td><a :href="'/admin/#auto-trading?trading='+x.id">{{x.name}}</a><small>{{x.exchange}} · {{x.account_alias}}</small></td><td>{{x.symbol}} · {{x.timeframe}}</td><td>{{tradingOnline(x)?(x.snapshot?.entries?'실행':'중지'):'연결 확인 필요'}}</td><td>{{x.snapshot?.position??'확인 전'}}</td><td>{{money(x.snapshot?.performance?.net)}}</td><td>{{date(x.last_seen)}}</td><td><button @click="editItem(x)">이름 변경</button><button :disabled="busy" @click="change(x.archived?'restore':'archive',x)">{{x.archived?'복원':'보관'}}</button></td></tr></tbody></table></div><p v-if="!shown.length">등록된 거래가 없거나 검색 조건에 맞지 않습니다.</p></template>
<template v-else><div ref="host"></div><section v-if="item" class="at-settings"><h2>거래 연결·등록 관리</h2><p>Binance 키 입력·계정 준비·HTTPS 연결은 거래 PC의 로컬 화면에서 관리합니다.</p><button :disabled="busy" @click="editItem(item)">이름 변경</button><button :disabled="busy" @click="pairCode">PC 연결 코드 발급</button><button :disabled="busy" @click="change('disconnect',item)">PC 연결 해제</button><div v-if="pair"><label>거래 PC 관리 화면에 입력할 일회용 코드<input :value="pair.code" readonly aria-label="일회용 PC 연결 코드"></label><p>유효 시각 {{date(pair.expires_at)}} · 한 번만 사용할 수 있습니다.</p></div></section></template>
</main></template>
<style scoped>.at-center{padding:12px 10px 40px}.at-center header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}.at-center h1{font-size:32px;font-weight:750;margin:10px 0}.at-center h2{font-size:21px;font-weight:700}.at-eyebrow{font-size:12px;color:#35628b;letter-spacing:1px}.at-toolbar{display:flex;gap:18px;align-items:end;flex-wrap:wrap;margin:22px 0}.at-center input,.at-center select{display:block;border:1px solid #a8bbcf;border-radius:7px;padding:10px;font:inherit;max-width:100%}.at-center input[type=checkbox]{display:inline}.at-center button{border:1px solid #9bb1c6;border-radius:7px;padding:9px 14px;background:#edf4fb;cursor:pointer;margin:5px}.at-center button:disabled{opacity:.4;cursor:wait}.at-table{overflow:auto}.at-table table{display:table;min-width:900px;width:100%;border-collapse:collapse}.at-table td,.at-table th{padding:15px 10px;text-align:left;border-bottom:1px solid #d6e1ed;vertical-align:top}.at-table small{display:block;color:#596d82;margin-top:6px}.at-form,.at-settings{border:1px solid #d2deeb;background:#f4f8fc;border-radius:12px;padding:22px;margin:22px 0}.at-form label,.at-settings label{display:block;margin:12px 0}.at-settings input{width:100%}.at-center [role=alert]{color:#9c2444}@media(max-width:700px){.at-center header{display:block}.at-center h1{font-size:27px}}
</style>
